import * as _smthrs_db_adapter from '@smthrs/db/adapter';

/**
 * Reclaim workspace-local sandbox transport roots after their owning run is
 * terminal. Unknown and nonterminal runs are always retained.
 *
 * @param {{
 *   cwd: string;
 *   adapter?: Pick<import("@smthrs/db/adapter").SmithersDb, "getRun">;
 *   sandboxDir?: string;
 *   olderThanMs?: number;
 *   nowMs?: number;
 *   dryRun?: boolean;
 *   sizeOf?: (path: string) => Promise<number>;
 *   warn?: (line: string) => void;
 * }} options
 */
declare function reapSandboxRoots(options: {
    cwd: string;
    adapter?: Pick<_smthrs_db_adapter.SmithersDb, "getRun">;
    sandboxDir?: string;
    olderThanMs?: number;
    nowMs?: number;
    dryRun?: boolean;
    sizeOf?: (path: string) => Promise<number>;
    warn?: (line: string) => void;
}): Promise<{
    sandboxDir: string;
    removed: any[];
    skipped: any[];
    bytesFreed: number;
    totalBytes: number;
    dryRun: boolean;
}>;

export { reapSandboxRoots };
